#!/usr/bin/env python3
"""Build a separate, locally signed special-battle Mac app. Never replace the campaign app."""
import hashlib,json,os,plistlib,shutil,subprocess
from pathlib import Path
root=Path(__file__).resolve().parent.parent
out=root/'dist/special-hulao-macos'
app=out/'虎牢关·体素特别版.app'
mac=app/'Contents/MacOS';res=app/'Contents/Resources'
mac.mkdir(parents=True,exist_ok=True);res.mkdir(parents=True,exist_ok=True)
def copy(source,destination):
    pending=Path(str(destination)+'.pending');shutil.copy2(source,pending);os.replace(pending,destination);return str(destination)
copy(root/'build-mac/caocao_prototype_app',mac/'caocao-prototype')
shutil.copytree(root/'assets/prototype',res/'assets',dirs_exist_ok=True,copy_function=copy)
launcher=mac/'launch'
launcher.write_text('#!/bin/sh\nset -eu\nbase="$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)"\nexec "$base/caocao-prototype" "$base/../Resources/assets" --special-hulao\n');launcher.chmod(0o755)
(app/'Contents/Info.plist').write_bytes(plistlib.dumps({'CFBundleIdentifier':'cc.3kingdoms.hulao.voxel','CFBundleName':'虎牢关·体素特别版','CFBundleDisplayName':'虎牢关·体素特别版','CFBundleExecutable':'launch','CFBundlePackageType':'APPL','CFBundleVersion':'14','CFBundleShortVersionString':'2.8.1','NSHighResolutionCapable':True,'LSMinimumSystemVersion':'12.0'}))
start=out/'Start Hulao.command';start.write_text('#!/bin/sh\nset -eu\ncd "$(dirname "$0")"\nexec "./虎牢关·体素特别版.app/Contents/MacOS/launch"\n');start.chmod(0o755)
for source,name in [('assets/generated/fonts/OFL.txt','FONT-LICENSE.txt'),('assets/presentation-font/OFL.txt','NOTO-SANS-LICENSE.txt'),('third_party/json.LICENSE.MIT','JSON-LICENSE.txt'),('.cache/SDL3-3.4.16/LICENSE.txt','SDL-LICENSE.txt')]:shutil.copy2(root/source,out/name)
(out/'README.txt').write_text('Hulao Pass — Voxel Special 2.8.1\n\nDouble-click 虎牢关·体素特别版.app or Start Hulao.command.\nChoose Cao Cao, Xiahou Yuan, Xiahou Dun, or Li Dian by clicking a card or pressing 1–4. Your opponent is randomly Lu Bu or Dong Zhuo (50% each), selected once per new match. Loading a save retains the whole lineup and combat random state. Existing saves keep their original lineup. Any surviving friendly hero can continue fighting and win alone. You lose only when all friendly units fall, or the 20-turn limit expires.\nAgainst Dong Zhuo, one random distinct hero joins your chosen hero (2 friendly units). Against Lu Bu, all three remaining heroes join your chosen hero (4 friendly units). You control every friendly unit. Teammates deploy at (10,12), (10,8), and (8,10). 28 voxel frames per character; 168 frames across six libraries. Henry’s stats, classes and equipment are retained: Xiahou Yuan uses a bow, Li Dian is infantry, and Lu Bu is a stronger opponent. New matches against Dong Zhuo start without Healing Beans (恢复用豆). Against Lu Bu, your team still starts with three shared Healing Beans. Loading an existing save keeps its inventory, including beans from older Dong Zhuo matches. Nearby starting positions; local enemy AI approaches and attacks. Defeat the opponent within 20 turns. No other units or campaign events.\nSelect your hero to show the larger blue movement grid. Click a destination to move, or click the hero’s current tile again (Space also works) to act without moving. Choose attack, then an enemy in range. An out-of-range attack stays disabled.\nEach rendered tent sits on its green Camp +20% healing square. Clicking the tent, including its roof, targets that same tile. Stay on one until your next turn to recover 20% of maximum HP, rounded down and capped at full HP. Merely entering the square does not heal. A green +HP number and before/after caption show recovery. The old offset backdrop tents have been removed.\nThe east gate (gold outline) is open: move through it into the courtyard. Walls remain blocked. Existing fixed Cao Cao/Dong Zhuo duel saves load without resetting progress; new schema19 Dong Zhuo saves require version 2.8.1 or newer; schema18 two/four-friendly saves require version 2.8 or newer; schema17 starter-supply saves require version 2.7 or newer; older one-ally saves retain their original lineup. Unfinished schema14 matches upgrade in memory without changing actions or RNG; previously completed defeats remain ended. Historical schema11–13 saves retain their original lineup. Right-click or Control-click for unit details. E ends turn; Esc cancels movement.\nF5 save, F9 load, F6 ten slots and snapshot backup. R opens the hero chooser for a new match; Esc returns to an existing match. Saves are disabled while choosing.\nSpecial saves: ~/.local/share/caocao-prototype/special-hulao-duel-v1\nThis app does not replace the regular campaign app or its saves. Local AI, no credentials.\nFixed-camera illustration and alpha sprites; no rotatable 3D meshes.\nAd-hoc signed for this Mac, not notarized for public Mac distribution.\nWeb link: https://3kingdoms.cc.cd/special/hulao/\n')
subprocess.run(['codesign','--force','--sign','-',str(mac/'caocao-prototype')],check=True)
subprocess.run(['codesign','--force','--sign','-',str(app)],check=True)
subprocess.run(['codesign','--verify','--deep','--strict',str(app)],check=True)
(out/'SHA256.json').write_text(json.dumps({str(p.relative_to(out)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(out.rglob('*')) if p.is_file() and p.name!='SHA256.json'},indent=2))
print(app)
